// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title ModelRegistry - stores provenance information for trained ML models
contract ModelRegistry {
    struct Model {
        uint256 id;
        address owner;
        string modelHash;    // SHA-256 hex (as string)
        string datasetHash;  // SHA-256 hex (as string)
        string ipfsCid;      // Pinata CID / IPFS CID
        bytes32 merkleRoot;  // bytes32 merkle root (0x...)
        uint256 timestamp;
    }

    uint256 public nextId = 1;
    mapping(uint256 => Model) public models;

    event ModelRegistered(uint256 indexed id, address indexed owner, string ipfsCid, bytes32 merkleRoot);

    function registerModel(
        string calldata modelHash,
        string calldata datasetHash,
        string calldata ipfsCid,
        bytes32 merkleRoot
    ) external returns (uint256) {
        uint256 id = nextId++;
        models[id] = Model({
            id: id,
            owner: msg.sender,
            modelHash: modelHash,
            datasetHash: datasetHash,
            ipfsCid: ipfsCid,
            merkleRoot: merkleRoot,
            timestamp: block.timestamp
        });

        emit ModelRegistered(id, msg.sender, ipfsCid, merkleRoot);
        return id;
    }

    function getModel(uint256 id) external view returns (
        uint256, address, string memory, string memory, string memory, bytes32, uint256
    ) {
        Model storage m = models[id];
        return (m.id, m.owner, m.modelHash, m.datasetHash, m.ipfsCid, m.merkleRoot, m.timestamp);
    }
}

contracts/TrustmintMarketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/interfaces/IERC2981.sol";

/// @title TrustmintMarketplace - Marketplace for trading AI model NFTs
/// @notice Enables listing, buying, and selling of TrustmintNFT tokens
contract TrustmintMarketplace is ReentrancyGuard, Ownable {

    struct Listing {
        uint256 listingId;
        uint256 tokenId;
        address nftContract;
        address seller;
        uint256 price;
        bool active;
    }

    // Listing ID counter
    uint256 private _listingIds;

    // Platform fee (in basis points, e.g., 250 = 2.5%)
    uint256 public platformFee = 250; // 2.5%

    // Mapping from listing ID to Listing
    mapping(uint256 => Listing) public listings;

    // Mapping from token ID to listing ID (for quick lookup)
    mapping(address => mapping(uint256 => uint256)) public tokenToListing;

    // Events
    event ListingCreated(
        uint256 indexed listingId,
        uint256 indexed tokenId,
        address indexed seller,
        uint256 price
    );

    event ListingCancelled(uint256 indexed listingId);

    event ModelPurchased(
        uint256 indexed listingId,
        uint256 indexed tokenId,
        address seller,
        address buyer,
        uint256 price
    );

    event PlatformFeeUpdated(uint256 newFee);

    constructor() Ownable(msg.sender) {}

    /// @notice List an NFT for sale
    /// @param nftContract Address of the NFT contract
    /// @param tokenId Token ID to list
    /// @param price Sale price in wei
    /// @return listingId The ID of the created listing
    function listModel(
        address nftContract,
        uint256 tokenId,
        uint256 price
    ) external nonReentrant returns (uint256) {
        require(price > 0, "Price must be greater than zero");
        require(
            IERC721(nftContract).ownerOf(tokenId) == msg.sender,
            "Not the owner of this NFT"
        );
        require(
            IERC721(nftContract).isApprovedForAll(msg.sender, address(this)) ||
            IERC721(nftContract).getApproved(tokenId) == address(this),
            "Marketplace not approved"
        );
        require(
            tokenToListing[nftContract][tokenId] == 0,
            "Token already listed"
        );

        _listingIds++;
        uint256 listingId = _listingIds;

        listings[listingId] = Listing({
            listingId: listingId,
            tokenId: tokenId,
            nftContract: nftContract,
            seller: msg.sender,
            price: price,
            active: true
        });

        tokenToListing[nftContract][tokenId] = listingId;

        emit ListingCreated(listingId, tokenId, msg.sender, price);

        return listingId;
    }

    /// @notice Cancel an active listing
    /// @param listingId The listing ID to cancel
    function cancelListing(uint256 listingId) external nonReentrant {
        Listing storage listing = listings[listingId];
        require(listing.active, "Listing not active");
        require(listing.seller == msg.sender, "Not the seller");

        listing.active = false;
        tokenToListing[listing.nftContract][listing.tokenId] = 0;

        emit ListingCancelled(listingId);
    }

    /// @notice Purchase a listed NFT
    /// @param listingId The listing ID to purchase
    function purchaseModel(uint256 listingId) external payable nonReentrant {
        Listing storage listing = listings[listingId];
        require(listing.active, "Listing not active");
        require(msg.value >= listing.price, "Insufficient payment");
        require(msg.sender != listing.seller, "Seller cannot buy own NFT");

        listing.active = false;
        tokenToListing[listing.nftContract][listing.tokenId] = 0;

        // Calculate fees
        uint256 platformFeeAmount = (listing.price * platformFee) / 10000;
        uint256 royaltyAmount = 0;
        address royaltyReceiver = address(0);

        // Check for ERC2981 royalty support
        if (IERC721(listing.nftContract).supportsInterface(type(IERC2981).interfaceId)) {
            (royaltyReceiver, royaltyAmount) = IERC2981(listing.nftContract).royaltyInfo(
                listing.tokenId,
                listing.price
            );
        }

        // Calculate seller proceeds
        uint256 sellerProceeds = listing.price - platformFeeAmount - royaltyAmount;

        // Transfer NFT to buyer
        IERC721(listing.nftContract).safeTransferFrom(
            listing.seller,
            msg.sender,
            listing.tokenId
        );

        // Transfer funds
        (bool successSeller, ) = payable(listing.seller).call{value: sellerProceeds}("");
        require(successSeller, "Transfer to seller failed");

        if (royaltyAmount > 0 && royaltyReceiver != address(0)) {
            (bool successRoyalty, ) = payable(royaltyReceiver).call{value: royaltyAmount}("");
            require(successRoyalty, "Royalty transfer failed");
        }

        // Refund excess payment
        if (msg.value > listing.price) {
            (bool successRefund, ) = payable(msg.sender).call{value: msg.value - listing.price}("");
            require(successRefund, "Refund failed");
        }

        emit ModelPurchased(
            listingId,
            listing.tokenId,
            listing.seller,
            msg.sender,
            listing.price
        );
    }

    /// @notice Update platform fee (only owner)
    /// @param newFee New platform fee in basis points
    function setPlatformFee(uint256 newFee) external onlyOwner {
        require(newFee <= 1000, "Fee cannot exceed 10%");
        platformFee = newFee;
        emit PlatformFeeUpdated(newFee);
    }

    /// @notice Withdraw accumulated platform fees
    function withdrawFees() external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "No fees to withdraw");
        (bool success, ) = payable(owner()).call{value: balance}("");
        require(success, "Withdrawal failed");
    }

    /// @notice Get listing details
    /// @param listingId The listing ID
    /// @return Listing struct
    function getListing(uint256 listingId) external view returns (Listing memory) {
        return listings[listingId];
    }

    /// @notice Get total number of listings created
    /// @return uint256 Total listings
    function totalListings() external view returns (uint256) {
        return _listingIds;
    }

    /// @notice Check if token is listed
    /// @param nftContract NFT contract address
    /// @param tokenId Token ID
    /// @return bool True if listed
    function isListed(address nftContract, uint256 tokenId) external view returns (bool) {
        uint256 listingId = tokenToListing[nftContract][tokenId];
        return listingId != 0 && listings[listingId].active;
    }

    // Required to receive NFTs
    function onERC721Received(
        address,
        address,
        uint256,
        bytes memory
    ) public pure returns (bytes4) {
        return this.onERC721Received.selector;
    }
}

contracts/TrustmintNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/common/ERC2981.sol";

/// @title TrustmintNFT - NFT contract for AI models with proof-of-training
/// @notice Each NFT represents a unique AI model with cryptographic proofs
contract TrustmintNFT is ERC721, ERC721URIStorage, ERC2981, Ownable {
    uint256 private _tokenIds;

    // Struct to store model verification data
    struct ModelMetadata {
        string modelHash;      // SHA-256 of the model file
        string datasetHash;    // SHA-256 of the dataset
        bytes32 merkleRoot;    // Merkle root of training proof
        string ipfsCid;        // IPFS CID for model + dataset files
        address creator;       // Original creator/trainer
        uint256 timestamp;     // Block timestamp when minted
        bool verified;         // Verification status
    }

    // Mapping from token ID to model metadata
    mapping(uint256 => ModelMetadata) public modelMetadata;

    // Mapping to track if a model hash has been registered (prevent duplicates)
    mapping(string => bool) public registeredModels;

    // Marketplace contract address (authorized to transfer)
    address public marketplace;

    // Events
    event ModelMinted(
        uint256 indexed tokenId,
        address indexed creator,
        string modelHash,
        string ipfsCid
    );

    event ModelVerified(uint256 indexed tokenId, bool verified);
    event MarketplaceUpdated(address indexed marketplace);

    constructor() ERC721("TrustmintAI", "TMAI") Ownable(msg.sender) {
        // Set default royalty to 5% for contract owner
        _setDefaultRoyalty(msg.sender, 500); // 500 = 5%
    }

    /// @notice Mint a new AI model NFT
    /// @param modelHash SHA-256 hash of the model file
    /// @param datasetHash SHA-256 hash of the dataset
    /// @param merkleRoot Merkle root of the training proof
    /// @param ipfsCid IPFS CID where model and dataset are stored
    /// @param metadataUri IPFS URI for the metadata JSON
    /// @return tokenId The ID of the newly minted NFT
    function mintModel(
        string calldata modelHash,
        string calldata datasetHash,
        bytes32 merkleRoot,
        string calldata ipfsCid,
        string calldata metadataUri
    ) external returns (uint256) {
        require(bytes(modelHash).length > 0, "Model hash cannot be empty");
        require(bytes(ipfsCid).length > 0, "IPFS CID cannot be empty");
        require(!registeredModels[modelHash], "Model already registered");

        _tokenIds++;
        uint256 newTokenId = _tokenIds;

        // Mint NFT to the caller (model creator)
        _safeMint(msg.sender, newTokenId);
        _setTokenURI(newTokenId, metadataUri);

        // Store metadata
        modelMetadata[newTokenId] = ModelMetadata({
            modelHash: modelHash,
            datasetHash: datasetHash,
            merkleRoot: merkleRoot,
            ipfsCid: ipfsCid,
            creator: msg.sender,
            timestamp: block.timestamp,
            verified: true // Auto-verified for now; can add manual verification later
        });

        // Mark model as registered
        registeredModels[modelHash] = true;

        // Set royalty for this token (5% to creator)
        _setTokenRoyalty(newTokenId, msg.sender, 500);

        emit ModelMinted(newTokenId, msg.sender, modelHash, ipfsCid);

        return newTokenId;
    }

    /// @notice Get detailed metadata for a model NFT
    /// @param tokenId The NFT token ID
    function getModelMetadata(uint256 tokenId)
        external
        view
        returns (
            string memory modelHash,
            string memory datasetHash,
            bytes32 merkleRoot,
            string memory ipfsCid,
            address creator,
            uint256 timestamp,
            bool verified
        )
    {
        require(_ownerOf(tokenId) != address(0), "Token does not exist");
        ModelMetadata memory metadata = modelMetadata[tokenId];
        return (
            metadata.modelHash,
            metadata.datasetHash,
            metadata.merkleRoot,
            metadata.ipfsCid,
            metadata.creator,
            metadata.timestamp,
            metadata.verified
        );
    }

    /// @notice Verify a model's authenticity by comparing hashes
    /// @param tokenId The NFT token ID
    /// @param modelHash The hash to verify against
    /// @return bool True if hashes match
    function verifyModel(uint256 tokenId, string calldata modelHash)
        external
        view
        returns (bool)
    {
        require(_ownerOf(tokenId) != address(0), "Token does not exist");
        return keccak256(bytes(modelMetadata[tokenId].modelHash)) == keccak256(bytes(modelHash));
    }

    /// @notice Set the marketplace contract address
    /// @param _marketplace Address of the marketplace contract
    function setMarketplace(address _marketplace) external onlyOwner {
        require(_marketplace != address(0), "Invalid marketplace address");
        marketplace = _marketplace;
        emit MarketplaceUpdated(_marketplace);
    }

    /// @notice Update verification status (only owner)
    /// @param tokenId The NFT token ID
    /// @param verified New verification status
    function setVerificationStatus(uint256 tokenId, bool verified) external onlyOwner {
        require(_ownerOf(tokenId) != address(0), "Token does not exist");
        modelMetadata[tokenId].verified = verified;
        emit ModelVerified(tokenId, verified);
    }

    /// @notice Get total number of minted models
    /// @return uint256 Total supply
    function totalSupply() external view returns (uint256) {
        return _tokenIds;
    }

    // Override required functions
    function tokenURI(uint256 tokenId)
        public
        view
        override(ERC721, ERC721URIStorage)
        returns (string memory)
    {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721URIStorage, ERC2981)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    function _update(address to, uint256 tokenId, address auth)
        internal
        override(ERC721)
        returns (address)
    {
        return super._update(to, tokenId, auth);
    }
}

